<?php
declare(strict_types=1);
namespace Tests\Unit\Modules\Identity\Application;
use App\Modules\Identity\Application\{RestrictedTenantProbePlan,RestrictedTenantProbeScope,RestrictedTenantProbeTransport,TenantAuthorityAuthenticator,TenantAuthorityBridge,TenantRestrictedProbeCoordinator};
use App\Modules\Identity\Domain\{TenantHostContext,TenantStaffContext};
use App\Modules\Identity\Infrastructure\Persistence\TenantStaffUser;
use Illuminate\Http\Request;use Illuminate\Session\{ArraySessionHandler,Store};use LogicException;use Tests\TestCase;
final class TenantRestrictedProbeCoordinatorTest extends TestCase {
 private function request():Request{$r=Request::create('/','POST');$s=new Store('r',new ArraySessionHandler(60));$s->start();$r->setLaravelSession($s);return $r;}
 private function host():TenantHostContext{return new TenantHostContext('tenant-A','a','a.test','test','LOCAL_TEST');}
 private function coordinator(array &$seen, bool $reject=false):TenantRestrictedProbeCoordinator{$auth=new class implements TenantAuthorityAuthenticator{public function authenticate(TenantHostContext $h,string $e,string $p,string $k,Request $r):TenantStaffUser{$r->session()->migrate(true);$r->attributes->set('tenant_staff_context',new TenantStaffContext($h->tenantId,$h->hostname,'user','membership',1,1));$r->session()->put('identity.tenant_staff',['authority_generation'=>'g1']);return new TenantStaffUser;}};$transport=new class($seen,$reject) implements RestrictedTenantProbeTransport{public function __construct(private array &$seen,private bool $reject){}public function beginBound(TenantStaffContext $c,string $g,RestrictedTenantProbePlan $p):RestrictedTenantProbeScope{if($this->reject)throw new LogicException('affinity rejected before write');$this->seen[]=[$c->tenantId,$g,$p->operation,'bound'];return new class($this->seen) implements RestrictedTenantProbeScope{public function __construct(private array &$seen){}public function execute():array{$this->seen[]='write';return ['outcome'=>'ALLOWED','row_effects'=>1];}public function close():void{$this->seen[]='close';}};}};return new TenantRestrictedProbeCoordinator(new TenantAuthorityBridge($auth),$transport);}
 public function test_real_bridge_composition_requires_matching_actor_and_affinity():void{$seen=[];$p=new RestrictedTenantProbePlan('run','case','tenant-A','read','c1','t1');$r=$this->coordinator($seen)->authenticateAndExecute($this->host(),'a','p','retry',$this->request(),$p);self::assertSame('ALLOWED',$r['outcome']);self::assertSame([['tenant-A','g1','read','bound'],'write','close'],$seen);}
 public function test_rejects_cross_tenant_and_wrong_transport_before_write():void{$seen=[];try{$this->coordinator($seen)->authenticateAndExecute($this->host(),'a','p','r',$this->request(),new RestrictedTenantProbePlan('run','case','tenant-B','read','c1','t1'));self::fail('cross accepted');}catch(LogicException){self::addToAssertionCount(1);}try{$this->coordinator($seen,true)->authenticateAndExecute($this->host(),'a','p','r',$this->request(),new RestrictedTenantProbePlan('run','case2','tenant-A','read','c1','t1'));self::fail('affinity accepted');}catch(LogicException){self::assertSame([],$seen);}}
}
